import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"OCSE: the 9-step install wizard and the OCSECL command dictionary","description":"","frontmatter":{},"headers":[],"relativePath":"components/ocse/ocse-wizard.md","filePath":"components/ocse/ocse-wizard.md"}'),r={name:"components/ocse/ocse-wizard.md"};function c(s,t,i,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="ocse-the-9-step-install-wizard-and-the-ocsecl-command-dictionary" tabindex="-1">OCSE: the 9-step install wizard and the OCSECL command dictionary <a class="header-anchor" href="#ocse-the-9-step-install-wizard-and-the-ocsecl-command-dictionary" aria-label="Permalink to &quot;OCSE: the 9-step install wizard and the OCSECL command dictionary&quot;">​</a></h1><p>The installer offers two doors onto the <strong>same</strong> command surface: the graphical wizard (the default) and the OCSECL shell. The wizard implements <strong>no install logic of its own</strong> - every mutating action it performs is a real OCSECL command line executed through <code>ocse_cl_exec</code>, which is exactly what the shell would run. A failed command shows its captured output on the error page with Retry/Back.</p><h2 id="the-nine-steps" tabindex="-1">The nine steps <a class="header-anchor" href="#the-nine-steps" aria-label="Permalink to &quot;The nine steps&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Page</th><th>What happens</th></tr></thead><tbody><tr><td>1</td><td>Welcome + language</td><td>language pick (English / Simplified Chinese); the whole UI, wizard included, follows the choice live</td></tr><tr><td>2</td><td>Target disk</td><td><code>lsdisk</code> lists the install-target disks; a disk that already boots <code>opencube.elf</code> is refused (the existing-system check)</td></tr><tr><td>3</td><td>Partitioning</td><td><code>lspart &lt;disk&gt;</code> lists partitions and free gaps; the wizard preselects the <strong>largest free gap</strong> and builds <code>mkpart &lt;disk&gt; &lt;startMiB&gt; &lt;endMiB&gt;</code>; Advanced options can delete a partition (<code>rmpart ... confirm</code>)</td></tr><tr><td>4</td><td>Formatting</td><td><code>mkfs.fat32 &lt;device&gt; confirm</code> - FAT32 is the OCBL boot-partition contract; the page explains that formatting destroys the data on that partition only</td></tr><tr><td>5</td><td>User account</td><td>name, full name and password; the password is hashed to a 64-hex SHA-256 <strong>before it leaves the page</strong> - the record written later is <code>name:full:sha256</code>, never a plain password</td></tr><tr><td>6</td><td>System configuration</td><td>hostname, language, update URL, automatic update check</td></tr><tr><td>7</td><td>Review</td><td>everything above, one screen, before anything is written</td></tr><tr><td>8</td><td>Install</td><td>the real command sequence, stage by stage (below)</td></tr><tr><td>9</td><td>Done</td><td>finish or reboot into the installed system</td></tr></tbody></table><h2 id="step-8-the-six-install-stages" tabindex="-1">Step 8: the six install stages <a class="header-anchor" href="#step-8-the-six-install-stages" aria-label="Permalink to &quot;Step 8: the six install stages&quot;">​</a></h2><p>Each stage is a real command line; the progress bar tracks the stages, and the first failure jumps to the error page carrying the failed command and its captured output.</p><table tabindex="0"><thead><tr><th>Stage</th><th>Command (built)</th><th>Notes</th></tr></thead><tbody><tr><td>1. Mount</td><td><code>mount &lt;device&gt; /mnt</code></td><td>a stale mount from a failed retry is dropped (<code>umount /mnt</code>) and the mount retried once</td></tr><tr><td>2. Install</td><td><code>install &lt;disk&gt; &lt;n&gt; confirm</code></td><td>the full install state machine: medium check, FAT gate, payload extract, boot code, boot flag</td></tr><tr><td>3. Config</td><td><code>config set hostname &lt;h&gt;</code> then <code>config set lang &lt;en|zh&gt;</code>, optional <code>config set update_url &lt;u&gt;</code>, <code>config set auto_check &lt;0|1&gt;</code></td><td>four keys on the installed config</td></tr><tr><td>4. User record</td><td><code>write /mnt/etc/users &lt;name&gt;:&lt;full&gt;:&lt;sha256&gt;</code></td><td>the SHA-256 password hash; a record that cannot fit is refused, never truncated</td></tr><tr><td>5. Sync</td><td><code>sync</code></td><td>flush the block cache</td></tr><tr><td>6. Unmount</td><td><code>umount /mnt</code></td><td>the target is left clean</td></tr></tbody></table><h2 id="the-ocsecl-command-dictionary-40-commands" tabindex="-1">The OCSECL command dictionary (40 commands) <a class="header-anchor" href="#the-ocsecl-command-dictionary-40-commands" aria-label="Permalink to &quot;The OCSECL command dictionary (40 commands)&quot;">​</a></h2><p>The shell is always reachable from the panel (hotkey) and from the serial console. <code>help</code> lists everything; <code>help &lt;cmd&gt;</code> shows one command.</p><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>help</code></td><td>show all commands or one command&#39;s help</td></tr><tr><td><code>lsdisk</code></td><td>list install-target disks</td></tr><tr><td><code>lspart &lt;disk&gt;</code></td><td>list partitions of a disk</td></tr><tr><td><code>parted &lt;disk&gt;</code></td><td>show the raw partition table</td></tr><tr><td><code>mkpart &lt;disk&gt; &lt;startMiB&gt; &lt;endMiB&gt;</code></td><td>create a partition</td></tr><tr><td><code>rmpart &lt;disk&gt; &lt;n&gt; confirm</code></td><td>delete partition #n (needs <code>confirm</code>)</td></tr><tr><td><code>setflag &lt;disk&gt; &lt;n&gt; boot [on\\|off]</code></td><td>set a partition flag</td></tr><tr><td><code>mkfs.fat32 &lt;device&gt; confirm</code></td><td>format FAT32 (DESTROYS DATA; needs <code>confirm</code>)</td></tr><tr><td><code>mkfs.exfat &lt;device&gt; confirm</code></td><td>format exFAT (DESTROYS DATA; needs <code>confirm</code>)</td></tr><tr><td><code>mkfs.ext4 &lt;device&gt; confirm</code></td><td>format ext4 (DESTROYS DATA; needs <code>confirm</code>)</td></tr><tr><td><code>mount &lt;device&gt; &lt;path&gt;</code></td><td>mount (filesystem auto-detected)</td></tr><tr><td><code>umount &lt;path&gt;</code></td><td>unmount the filesystem at path</td></tr><tr><td><code>ls [path]</code></td><td>list a directory</td></tr><tr><td><code>cd [path]</code></td><td>change directory (default <code>/</code>)</td></tr><tr><td><code>pwd</code></td><td>print the working directory</td></tr><tr><td><code>cat &lt;file&gt;</code></td><td>print a text file</td></tr><tr><td><code>write &lt;file&gt; [text ...]</code></td><td>write one line</td></tr><tr><td><code>touch &lt;file&gt;</code></td><td>create an empty file</td></tr><tr><td><code>cp &lt;src&gt; &lt;dst&gt;</code></td><td>copy a file</td></tr><tr><td><code>mv &lt;src&gt; &lt;dst&gt;</code></td><td>move or rename a file</td></tr><tr><td><code>rm &lt;file&gt;</code></td><td>delete a file</td></tr><tr><td><code>mkdir &lt;path&gt;</code></td><td>create a directory</td></tr><tr><td><code>rmdir &lt;path&gt;</code></td><td>delete an empty directory</td></tr><tr><td><code>tar -t &lt;arc&gt;</code> / <code>tar -x &lt;arc&gt; [dir]</code></td><td>ustar list / extract</td></tr><tr><td><code>dd if= of= [bs= count= skip= seek=] [confirm]</code></td><td>block copy</td></tr><tr><td><code>sha256sum &lt;file&gt;</code> / <code>&lt;dev&gt; &lt;sectors&gt;</code></td><td>SHA-256 digest of a file or a disk span</td></tr><tr><td><code>install &lt;disk&gt; &lt;n&gt; confirm</code></td><td>install OCOS onto a partition</td></tr><tr><td><code>ocbl-install &lt;disk&gt; confirm</code></td><td>write the OCBL boot code</td></tr><tr><td><code>config [set &lt;k&gt; &lt;v&gt;]</code></td><td>show/edit the installed config</td></tr><tr><td><code>sync</code></td><td>flush the block cache to the disks</td></tr><tr><td><code>reboot</code></td><td>flush disks and reboot</td></tr><tr><td><code>shutdown</code></td><td>flush disks and power off</td></tr><tr><td><code>hwcheck</code></td><td>re-run the four hardware checks</td></tr><tr><td><code>disks</code></td><td>raw disk inventory</td></tr><tr><td><code>lang [en\\|zh]</code></td><td>show or set the language</td></tr><tr><td><code>serial_encoding [utf8\\|gbk]</code></td><td>show/set the serial line encoding</td></tr><tr><td><code>clear</code></td><td>clear the screen</td></tr><tr><td><code>click &lt;x&gt; &lt;y&gt;</code></td><td>probe the GUI button geometry (diagnostics)</td></tr><tr><td><code>gui</code></td><td>switch back to the graphical panel</td></tr><tr><td><code>halt</code></td><td>stop the CPU (no ACPI path)</td></tr></tbody></table><p>Next: <a href="./ocse-recovery.html">install failures and recovery</a>.</p>',11)])])}const p=e(r,[["render",c]]);export{g as __pageData,p as default};
